use filmcraft_color::{ColorInfo,ColorSpace,ColorPipeline,WorkingSpace,Transfer,Primaries,Matrix,HdrMetadata};use filmcraft_project::{Project,ItemId};use filmcraft_frame::VideoFrame;use filmcraft_render::colorman;use serde_json::{Value,json};
fn main(){let base:Value=serde_json::from_slice(&std::fs::read(std::env::args().nth(1).unwrap()).unwrap()).unwrap();let mut cases=vec![];
let colors=[ColorInfo::SRGB_FULL,ColorInfo::REC709,ColorInfo{transfer:Transfer::Linear,..ColorInfo::SRGB_FULL},ColorInfo{transfer:Transfer::Pq,primaries:Primaries::Bt2020,matrix:Matrix::Bt2020Ncl,..ColorInfo::SRGB_FULL},ColorInfo{transfer:Transfer::Hlg,primaries:Primaries::Bt2020,matrix:Matrix::Bt2020Ncl,..ColorInfo::SRGB_FULL},ColorInfo{primaries:Primaries::P3D65,..ColorInfo::SRGB_FULL}];
let profiles:Vec<_>=ColorSpace::ALL.into_iter().map(|cs|(ColorInfo::SRGB_FULL,Some(cs))).chain(colors.into_iter().map(|color|(color,None))).collect();
let rgba:Vec<u8>=(0..35).flat_map(|i|[((i*37+11)%256)as u8,((i*73+51)%256)as u8,((i*19+83)%256)as u8,[0,1,64,128,255][i%5]]).collect();
for(color,override_space)in profiles{for working in WorkingSpace::ALL{for wide_gamut in [false,true]{for auto_tone_map in [false,true]{let pipe=ColorPipeline{working,wide_gamut,auto_tone_map};for peak in [None,Some(3999.75f32)]{
 let mut document=base["cases"][0]["document"].clone();let media=&mut document["project"]["items"]["1"]["kind"]["Media"];media["interpret"]["color_space"]=json!(override_space);media["info"]["video"]["hdr"]=json!(peak.map(|p|HdrMetadata{max_cll:Some(p),mastering_max_nits:Some(5000.),mastering_min_nits:None,max_fall:None}));let project:Project=serde_json::from_value(document["project"].clone()).unwrap();let mut frame=VideoFrame::rgba8(7,5,rgba.clone());frame.color=color;
 for n in [1,2,3]{let image=colorman::decode(&project,ItemId(1),&frame,n,&pipe);let mut display=image.clone();colorman::to_display(&mut display,&pipe);cases.push(json!({"width":7,"height":5,"rgba":rgba,"color":color,"override":override_space,"pipeline":pipe,"peak":peak,"n":n,"outputWidth":image.w,"outputHeight":image.h,"bits":image.px.iter().map(|v|v.to_bits()).collect::<Vec<_>>(),"displayBits":display.px.iter().map(|v|v.to_bits()).collect::<Vec<_>>(),"displayRgba":display.to_rgba8()}));}
}}}}}
println!("{}",json!({"commit":"5231852443363f001c3f6b396dd9b1e6461ae2be","cases":cases}));}
